  const data=JSON.stringify({W,H,pl:pl+ip,pr:pr+ip,pt,pb,n,ys:m.ys,mode:m.mode,mx:m.mx,ser:vis.filter(s=>s.a>.5).map(s=>({p:s.p,v:s.v})),win:m.win,turn:m.turn}).replace(/'/g,'&#39;');
