  const A0=eAlly(),sumTxt=`${esc(eObjN())} · ${p?esc(eSide(A0))+(A0.length>1?' (posible alianza)':''):'Panorama sin partido'} · rivales ${st.es.rv==='ali'?'en posible alianza':'por separado'}`;
